        if (nums1[i] <= nums2[j]) {
            merged.push(nums1[i++]);
        } else {
            merged.push(nums2[j++]);
        }
    }

    merged.push(...nums1.slice(i), ...nums2.slice(j));

    const n = merged.length;

    if (n % 2) {
        return merged[Math.floor(n / 2)];
    }

    return (merged[n / 2 - 1] + merged[n / 2]) / 2;
};

